+export interface JobEvent {
+  id: string;
+  job_id: string;
+  payload: string;
+  created_at: string;
+  consumed: boolean;
+}
+
+export const enqueue = async (
+  payload: string,
+  db?: PoolClient | Pool,
+): Promise<void> => {
+  const queryFn = db || pool;
+  const jobResult = await queryFn.query(
+    "INSERT INTO jobs (payload, status) VALUES ($1, 'ready') RETURNING id",
+    [payload],
+  );
+  const jobId = jobResult.rows[0].id;
+
+  // Publish event for external services (participates in caller's transaction if provided)
+  await queryFn.query(
+    "INSERT INTO job_events (job_id, payload) VALUES ($1, $2)",
+    [jobId, payload],
+  );
 };

 export const claimNext = async (): Promise<Job | null> => {
@@ -18,3 +41,23 @@ export const claimNext = async (): Promise<Job | null> => {
   await pool.query("UPDATE jobs SET status = 'claimed' WHERE id = $1", [row.id]);
   return { id: row.id, payload: row.payload };
 };
+
+export const getUnconsumedEvents = async (limit: number = 100): Promise<JobEvent[]> => {
+  const result = await pool.query(
+    `SELECT id, job_id, payload, created_at, consumed
+     FROM job_events
+     WHERE consumed = false
+     ORDER BY created_at ASC
+     LIMIT $1`,
+    [limit],
+  );
+  return result.rows;
+};
+
+export const markEventsConsumed = async (eventIds: string[]): Promise<void> => {
+  if (eventIds.length === 0) return;
+  await pool.query(
+    `UPDATE job_events SET consumed = true WHERE id = ANY($1)`,
+    [eventIds],
+  );
+};
diff --git a/src/server.ts b/src/server.ts
