--- /dev/null
+++ b/src/server.ts
@@ -0,0 +1,43 @@
+import http from "http";
+import { getUnconsumedEvents, markEventsConsumed } from "./jobs.ts";
+
+export const createServer = (): http.Server => {
+  return http.createServer(async (req, res) => {
+    try {
+      if (req.method === "GET" && req.url === "/events") {
+        const limit = new URL(`http://localhost${req.url}`).searchParams.get("limit");
+        const events = await getUnconsumedEvents(limit ? parseInt(limit) : 100);
+
+        res.writeHead(200, { "Content-Type": "application/json" });
+        res.end(JSON.stringify(events));
+        return;
+      }
+
+      if (req.method === "POST" && req.url === "/events/ack") {
+        let body = "";
+        req.on("data", (chunk) => {
+          body += chunk.toString();
+        });
+        req.on("end", async () => {
+          try {
+            const { eventIds } = JSON.parse(body);
+            await markEventsConsumed(eventIds);
+            res.writeHead(200, { "Content-Type": "application/json" });
+            res.end(JSON.stringify({ ok: true }));
+          } catch (e) {
+            res.writeHead(400, { "Content-Type": "application/json" });
+            res.end(JSON.stringify({ error: "Invalid request" }));
+          }
+        });
+        return;
+      }
+
+      res.writeHead(404, { "Content-Type": "application/json" });
+      res.end(JSON.stringify({ error: "Not found" }));
+    } catch (err) {
+      console.error(err);
+      res.writeHead(500, { "Content-Type": "application/json" });
+      res.end(JSON.stringify({ error: "Internal server error" }));
+    }
+  });
+};
